SELECT sku, product_name, pack_size, gtin, selling_price_inr, cost_price_inr, flow_type, units_per_case
FROM store.products
WHERE lower(product_name) LIKE '%atta%' AND pack_size = '5 kg';

SELECT sku, name, pack, case_units, case_kg, flow, price_inr, cost_inr
FROM store.products
WHERE lower(name) LIKE '%atta%' AND pack = '5 kg';

SELECT SUM(units_sold) AS total_units_sold
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= DATE '2026-06-01' AND date <= DATE '2026-06-30';
